import{_ as o,o as e,c as a,a2 as r}from"./chunks/framework.DHtetOlu.js";const p=JSON.parse('{"title":"Geometria (CAD)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/geometry.md","filePath":"guide/geometry.md"}'),d={name:"guide/geometry.md"};function i(s,t,n,c,l,m){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="geometria-cad" tabindex="-1">Geometria (CAD) <a class="header-anchor" href="#geometria-cad" aria-label="Permalink to &quot;Geometria (CAD)&quot;">​</a></h1><p>O desenho do MagFEM é <strong>paramétrico</strong>, no estilo do Onshape: você desenha à mão livre e depois prende a forma com <strong>restrições</strong> (horizontal, tangente, coincidente…) e <strong>cotas</strong> (distâncias, raios, ângulos). As cotas aceitam unidades e expressões com variáveis, então mudar uma variável redesenha o modelo inteiro. O solver de restrições é o PlaneGCS, o mesmo do FreeCAD.</p><h2 id="ferramentas-de-desenho" tabindex="-1">Ferramentas de desenho <a class="header-anchor" href="#ferramentas-de-desenho" aria-label="Permalink to &quot;Ferramentas de desenho&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ferramenta</th><th>Tecla</th><th>Uso</th></tr></thead><tbody><tr><td>Selecionar</td><td><code>S</code> ou <code>Esc</code></td><td>clique seleciona, Shift adiciona; arraste para mover</td></tr><tr><td>Medir (régua)</td><td><code>U</code></td><td>dois cliques medem distância; não muda o desenho</td></tr><tr><td>Linha / polilinha</td><td><code>L</code></td><td>cada clique continua a polilinha; termina ao fechar num ponto existente, com duplo clique ou com <code>Esc</code></td></tr><tr><td>Linha de construção</td><td><code>Shift+L</code></td><td>linha auxiliar: guia o desenho mas não forma regiões</td></tr><tr><td>Retângulo</td><td><code>R</code></td><td>dois cantos opostos (nasce agrupado, com H/V)</td></tr><tr><td>Retângulo pelo centro</td><td><code>Shift+R</code></td><td>centro e um canto (simétrico em torno do centro)</td></tr><tr><td>Círculo</td><td><code>C</code></td><td>centro e um ponto da borda</td></tr><tr><td>Arco por três pontos</td><td><code>A</code></td><td>início, fim e um ponto do arco</td></tr><tr><td>Arco pelo centro</td><td><code>Shift+A</code></td><td>centro, início e fim (o movimento do mouse escolhe o sentido)</td></tr><tr><td>Ponto</td><td><code>P</code></td><td>ponto livre (útil como referência de cotas)</td></tr></tbody></table><p>Os botões com uma setinha agrupam variantes (linha/construção, retângulo/pelo centro, arco por três pontos/pelo centro); o botão mostra a última variante usada.</p><h2 id="encaixes-snap" tabindex="-1">Encaixes (snap) <a class="header-anchor" href="#encaixes-snap" aria-label="Permalink to &quot;Encaixes (snap)&quot;">​</a></h2><p>Durante o desenho, o cursor encaixa, nesta ordem, em:</p><ol><li><strong>pontos</strong> existentes (pontas, centros, a Origem): o novo ponto passa a ser o mesmo ponto;</li><li><strong>pontos médios</strong> de linhas: cria a restrição &quot;ponto médio&quot;;</li><li><strong>curvas</strong>: cria &quot;ponto sobre a curva&quot;;</li><li><strong>eixos x e y</strong> (r e z no axissimétrico): cria uma restrição vertical ou horizontal com a Origem.</li></ol><p>Na linha, o segundo ponto também infere <strong>horizontal ou vertical</strong> quando está quase alinhado, e encaixa na interseção dessa direção com a curva mais próxima. Todas essas restrições aparecem na árvore (<strong>Geometria › Restrições</strong>) e podem ser apagadas.</p><div class="tip custom-block"><p class="custom-block-title">A Origem</p><p>Clicar na origem cria um ponto próprio com a restrição <strong>Coincidente</strong> com a Origem. Para soltar a peça, apague essa restrição. Desenhos antigos em que a curva usa a própria Origem mostram <strong>Soltar da origem</strong> no painel de propriedades.</p></div><h2 id="restricoes" tabindex="-1">Restrições <a class="header-anchor" href="#restricoes" aria-label="Permalink to &quot;Restrições&quot;">​</a></h2><p>Selecione as entidades e clique no botão da restrição (ou use a tecla).</p><table tabindex="0"><thead><tr><th>Restrição</th><th>Tecla</th><th>Entidades</th></tr></thead><tbody><tr><td>Coincidente</td><td><code>I</code></td><td>dois pontos, ou ponto e curva (ponto sobre)</td></tr><tr><td>Horizontal / Vertical</td><td><code>H</code> / <code>V</code></td><td>uma linha, ou dois pontos</td></tr><tr><td>Paralela / Perpendicular</td><td></td><td>duas linhas</td></tr><tr><td>Tangente</td><td><code>T</code></td><td>linha e arco/círculo, ou dois arcos/círculos</td></tr><tr><td>Igual</td><td><code>E</code></td><td>duas linhas (comprimento) ou dois arcos/círculos (raio)</td></tr><tr><td>Ponto médio</td><td><code>M</code></td><td>ponto e linha</td></tr><tr><td>Simétrica</td><td></td><td>dois pontos e um eixo (linha)</td></tr><tr><td>Concêntrica</td><td></td><td>dois arcos/círculos</td></tr><tr><td>Fixar</td><td></td><td>prende pontos na posição atual</td></tr></tbody></table><p>A cor mostra o estado: <strong>azul</strong> ainda tem graus de liberdade, <strong>preto</strong> (ou branco no tema escuro) está totalmente definido. A barra de status mostra quantos graus de liberdade faltam. Uma restrição que conflita com as outras é recusada, com uma mensagem na barra de status.</p><h2 id="cotas-e-variaveis" tabindex="-1">Cotas e variáveis <a class="header-anchor" href="#cotas-e-variaveis" aria-label="Permalink to &quot;Cotas e variáveis&quot;">​</a></h2><p>Com a ferramenta <strong>Cota</strong> (<code>D</code>), clique numa entidade (ou em duas) e depois onde quer o texto; digite o valor.</p><ul><li>Uma linha ou dois pontos dão distância; a posição do texto escolhe entre a distância <strong>alinhada</strong>, <strong>horizontal</strong> ou <strong>vertical</strong>.</li><li>Um círculo dá diâmetro; um arco dá raio; duas linhas dão ângulo; ponto e linha dão a distância ponto-linha.</li><li>O valor aceita número (na unidade do projeto), número com unidade (<code>2 cm</code>, <code>0.5 in</code>) ou expressão com variáveis (<code>Ds/2 - g</code>).</li></ul><p>As variáveis ficam em <strong>Geometria › Variáveis</strong> (<code>+</code> cria). Um duplo clique numa cota edita o valor.</p><h2 id="editar" tabindex="-1">Editar <a class="header-anchor" href="#editar" aria-label="Permalink to &quot;Editar&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ação</th><th>Tecla</th><th>Descrição</th></tr></thead><tbody><tr><td>Tesoura</td><td><code>X</code></td><td>clique no trecho da curva para removê-lo, até as interseções mais próximas. Numa ponta, encurta; no meio, divide em duas; um círculo cortado vira arco; uma curva sem cruzamentos é apagada</td></tr><tr><td>Offset</td><td><code>O</code></td><td>cópia paralela a uma distância (associativa: segue o original)</td></tr><tr><td>Espelho</td><td></td><td>reflete a seleção em torno de uma linha ou eixo</td></tr><tr><td>Padrão linear / circular</td><td></td><td>cópias em grade ou em volta de um centro</td></tr><tr><td>Mover / girar</td><td><code>G</code></td><td>translada e gira a seleção por valores digitados</td></tr><tr><td>Agrupar / Desagrupar</td><td><code>Ctrl+G</code> / <code>Ctrl+Shift+G</code></td><td>o grupo é selecionado e movido como uma peça; duplo clique entra no grupo para editar uma entidade</td></tr><tr><td>Construção</td><td><code>Q</code></td><td>alterna a curva entre normal e de construção</td></tr><tr><td>Apagar</td><td><code>Del</code></td><td>apaga a seleção</td></tr><tr><td>Ajustar à tela</td><td><code>F</code></td><td>enquadra o desenho</td></tr><tr><td>Desfazer / Refazer</td><td><code>Ctrl+Z</code> / <code>Ctrl+Shift+Z</code> (ou <code>Ctrl+Y</code>)</td><td></td></tr></tbody></table><p>Offset, espelho e padrões são <strong>associativos</strong>: a cópia acompanha o original quando ele muda, e a distância ou o número de cópias ficam editáveis nas propriedades.</p><h2 id="selecao-por-caixa" tabindex="-1">Seleção por caixa <a class="header-anchor" href="#selecao-por-caixa" aria-label="Permalink to &quot;Seleção por caixa&quot;">​</a></h2><p>Como nos CADs, arrastar uma caixa <strong>para a direita</strong> seleciona o que está inteiramente dentro dela; <strong>para a esquerda</strong>, seleciona tudo que ela toca.</p><h2 id="plano-e-axissimetrico" tabindex="-1">Plano e axissimétrico <a class="header-anchor" href="#plano-e-axissimetrico" aria-label="Permalink to &quot;Plano e axissimétrico&quot;">​</a></h2><p>Na gaveta <strong>Problema e bibliotecas</strong> escolha o tipo de problema e a <strong>unidade</strong> de comprimento:</p><ul><li><strong>Plano</strong>: x e y; informe a <strong>profundidade</strong> (comprimento na direção z), usada no fluxo concatenado, na energia e na força.</li><li><strong>Axissimétrico</strong>: r (horizontal) e z (vertical), com o eixo de simetria em r = 0. Só o semiplano r ≥ 0 vale; ele fica destacado e o MagFEM avisa quando algo é desenhado em r &lt; 0.</li></ul><h2 id="importar-geometria" tabindex="-1">Importar geometria <a class="header-anchor" href="#importar-geometria" aria-label="Permalink to &quot;Importar geometria&quot;">​</a></h2><p><strong>Importar</strong> aceita DXF e SVG: as curvas entram no desenho e pontos coincidentes são unidos, para as regiões fecharem. Veja também <a href="./files.html">Arquivos, importar e exportar</a>.</p>',28)])])}const h=o(d,[["render",i]]);export{p as __pageData,h as default};
